CREATE TABLE public.phone_entry_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), phone text NOT NULL CHECK(phone ~ '^[6-9][0-9]{9}$'), device_hash text NOT NULL UNIQUE CHECK(length(device_hash)=64), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), account_id uuid, created_at timestamptz NOT NULL DEFAULT now(), reviewed_at timestamptz, reviewed_by uuid);
GRANT SELECT ON public.phone_entry_requests TO authenticated; GRANT ALL ON public.phone_entry_requests TO service_role;
ALTER TABLE public.phone_entry_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY phone_entry_admin_read ON public.phone_entry_requests FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.request_phone_entry(_phone text,_hash text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; BEGIN IF _phone !~ '^[6-9][0-9]{9}$' OR _hash !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'INVALID_REQUEST'; END IF; INSERT INTO phone_entry_requests(phone,device_hash) VALUES(_phone,_hash) ON CONFLICT(device_hash) DO NOTHING RETURNING id INTO result; IF result IS NULL THEN SELECT id INTO result FROM phone_entry_requests WHERE device_hash=_hash AND phone=_phone; END IF; IF result IS NULL THEN RAISE EXCEPTION 'DEVICE_ALREADY_USED'; END IF; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.request_phone_entry(text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.request_phone_entry(text,text) TO anon,authenticated;
CREATE FUNCTION public.review_phone_entry(_id uuid,_approve boolean,_account uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'ADMIN_ONLY'; END IF; IF _account IS NOT NULL AND NOT EXISTS(SELECT 1 FROM profiles WHERE id=_account AND right(regexp_replace(phone,'\D','','g'),10)=(SELECT phone FROM phone_entry_requests WHERE id=_id)) THEN RAISE EXCEPTION 'ACCOUNT_PHONE_MISMATCH'; END IF; UPDATE phone_entry_requests SET status=CASE WHEN _approve THEN 'approved' ELSE 'rejected' END, account_id=_account,reviewed_at=now(),reviewed_by=auth.uid() WHERE id=_id AND status='pending'; IF NOT FOUND THEN RAISE EXCEPTION 'NOT_PENDING'; END IF; END $$;
REVOKE ALL ON FUNCTION public.review_phone_entry(uuid,boolean,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.review_phone_entry(uuid,boolean,uuid) TO authenticated;